DROP TABLE IF EXISTS `order_audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_audit_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `action_type` varchar(60) NOT NULL COMMENT 'status_transition|payment_status_update|refund_processed|cancel_request|reconciliation_fix|etc',
  `previous_status` varchar(40) DEFAULT NULL,
  `new_status` varchar(40) DEFAULT NULL,
  `payment_status` varchar(40) DEFAULT NULL,
  `admin_id` bigint(20) unsigned DEFAULT NULL,
  `admin_role` varchar(40) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `message` varchar(255) DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_oal_order_id` (`order_id`),
  KEY `idx_oal_action_type` (`action_type`),
  KEY `idx_oal_created_at` (`created_at`),
  KEY `idx_oal_admin_id` (`admin_id`),
  CONSTRAINT `fk_oal_admin_id` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_oal_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Immutable audit trail for order governance and financial control actions';
