--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(40) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `customer_name` varchar(120) NOT NULL,
  `customer_email` varchar(190) NOT NULL,
  `customer_phone` varchar(25) NOT NULL,
  `customer_phone_e164` varchar(20) DEFAULT NULL,
  `fulfilment_mode` enum('delivery','pickup','custom_delivery') NOT NULL,
  `order_status` varchar(64) NOT NULL DEFAULT 'pending',
  `payment_status` enum('pending','under_review','paid','credit','refund_pending','partially_refunded','refunded','failed','rejected') NOT NULL DEFAULT 'pending',
  `refund_status` enum('none','requested','approved','rejected','processed') NOT NULL DEFAULT 'none',
  `refund_amount` decimal(10,2) DEFAULT NULL,
  `total_refunded` decimal(10,2) NOT NULL DEFAULT 0.00,
  `refund_reason` varchar(100) DEFAULT NULL,
  `refund_notes` text DEFAULT NULL,
  `refunded_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `refund_approved_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `refund_requested_at` datetime DEFAULT NULL,
  `refunded_at` datetime DEFAULT NULL,
  `payment_method` enum('upi_manual','cod','gateway','credit') NOT NULL DEFAULT 'upi_manual',
  `order_source` enum('retail','byoc_quote') NOT NULL DEFAULT 'retail',
  `order_mode` enum('ready_pos','scheduled_custom','online','byoc') DEFAULT NULL COMMENT 'POS mode: ready_pos=counter sale, scheduled_custom=admin booked, online=web, byoc=quote',
  `byoc_quote_id` bigint(20) unsigned DEFAULT NULL,
  `scheduled_slot` datetime DEFAULT NULL,
  `scheduled_slot_label` varchar(120) DEFAULT NULL,
  `slot_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK to order_slots.id ├óΓé¼ΓÇ¥ denormalized for fast fulfillment queries',
  `requires_kitchen_production` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0 for ready_pos orders (cake already made), 1 for all others',
  `production_status` enum('not_required','pending','in_production','decoration_pending','ready','packed','out_for_delivery','delivered') NOT NULL DEFAULT 'pending' COMMENT 'Kitchen production lifecycle',
  `delivery_postal_code` varchar(15) DEFAULT NULL,
  `billing_address_line1` varchar(190) DEFAULT NULL,
  `billing_address_line2` varchar(190) DEFAULT NULL,
  `billing_city` varchar(100) DEFAULT NULL,
  `billing_state` varchar(100) DEFAULT NULL,
  `billing_postal_code` varchar(15) DEFAULT NULL,
  `delivery_street` varchar(255) DEFAULT NULL,
  `delivery_maps_link` varchar(500) DEFAULT NULL,
  `delivery_distance_km` decimal(5,2) DEFAULT NULL,
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(10,2) NOT NULL,
  `discount_total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `tax_total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(10,2) NOT NULL,
  `advance_amount` decimal(10,2) DEFAULT NULL,
  `advance_received_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `followup_status` varchar(40) NOT NULL DEFAULT 'no_reminder',
  `followup_count` int(10) unsigned NOT NULL DEFAULT 0,
  `collection_priority` varchar(20) NOT NULL DEFAULT 'normal',
  `collection_note` text DEFAULT NULL,
  `last_followup_at` datetime DEFAULT NULL,
  `next_followup_at` datetime DEFAULT NULL,
  `outstanding_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `amount_collected` decimal(10,2) NOT NULL DEFAULT 0.00,
  `net_collected_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `balance_due_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `collection_status` varchar(40) NOT NULL DEFAULT 'payment_pending',
  `payment_proof_url` varchar(500) DEFAULT NULL,
  `payment_proof_uploaded_at` datetime DEFAULT NULL,
  `payment_confirmed_at` datetime DEFAULT NULL,
  `payment_confirmed_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `credit_collected_at` datetime DEFAULT NULL,
  `credit_collected_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `admin_note` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `archived_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `archive_reason_code` varchar(64) DEFAULT NULL,
  `archive_reason_notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  UNIQUE KEY `uq_orders_byoc_quote` (`byoc_quote_id`),
  KEY `user_id` (`user_id`),
  KEY `idx_orders_number` (`order_number`),
  KEY `idx_orders_email` (`customer_email`),
  KEY `idx_orders_status` (`order_status`),
  KEY `idx_orders_source` (`order_source`),
  KEY `idx_orders_order_mode` (`order_mode`),
  KEY `idx_orders_production_status` (`production_status`),
  KEY `idx_orders_slot_id` (`slot_id`),
  KEY `idx_orders_archived_state` (`is_archived`,`archived_at`,`order_status`),
  KEY `idx_orders_refund_status` (`refund_status`),
  KEY `idx_orders_followup_status` (`followup_status`),
  KEY `idx_orders_collection_priority` (`collection_priority`),
  CONSTRAINT `fk_orders_byoc_quote` FOREIGN KEY (`byoc_quote_id`) REFERENCES `byoc_quotes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_orders_slot_id` FOREIGN KEY (`slot_id`) REFERENCES `order_slots` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

