--
-- Table structure for table `refund_approval_logs`
--

DROP TABLE IF EXISTS `refund_approval_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund_approval_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `refund_transaction_id` bigint(20) unsigned NOT NULL,
  `action` enum('submitted','approved','rejected','escalated') NOT NULL,
  `performed_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `admin_role` varchar(40) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ral_refund_id` (`refund_transaction_id`),
  KEY `idx_ral_admin_id` (`performed_by_admin_id`),
  KEY `idx_ral_created_at` (`created_at`),
  CONSTRAINT `fk_ral_admin_id` FOREIGN KEY (`performed_by_admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ral_refund_id` FOREIGN KEY (`refund_transaction_id`) REFERENCES `refund_transactions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only audit log for every approval action taken on a refund';
/*!40101 SET character_set_client = @saved_cs_client */;

