--
-- Table structure for table `refund_transactions`
--

DROP TABLE IF EXISTS `refund_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `refund_number` varchar(40) NOT NULL COMMENT 'Unique human-readable ref, e.g. RFD-20260527-0001',
  `refund_type` enum('full','partial') NOT NULL,
  `reason_code` varchar(100) NOT NULL COMMENT 'Standardised code, e.g. DAMAGED_ITEM, WRONG_ORDER',
  `reason_notes` text DEFAULT NULL,
  `requested_amount` decimal(10,2) NOT NULL COMMENT 'Amount requested by admin; capped at grand_total - delivery_fee',
  `approved_amount` decimal(10,2) DEFAULT NULL COMMENT 'Final approved amount; may differ from requested_amount',
  `processed_amount` decimal(12,2) DEFAULT NULL,
  `status` enum('pending_approval','approved','rejected','processed') NOT NULL DEFAULT 'pending_approval',
  `refund_status` varchar(40) NOT NULL DEFAULT 'pending_approval',
  `requested_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `approved_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `previous_order_status` varchar(40) DEFAULT NULL COMMENT 'Snapshot of order_status at request time; used to revert on rejection',
  `fraud_flags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of triggered fraud-check codes, e.g. ["DUPLICATE_REFUND"]' CHECK (json_valid(`fraud_flags`)),
  `requested_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `refund_closed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rt_refund_number` (`refund_number`),
  KEY `idx_rt_order_id` (`order_id`),
  KEY `idx_rt_status` (`status`),
  KEY `idx_rt_requested_by` (`requested_by_admin_id`),
  KEY `idx_rt_requested_at` (`requested_at`),
  KEY `fk_rt_approved_by` (`approved_by_admin_id`),
  CONSTRAINT `fk_rt_approved_by` FOREIGN KEY (`approved_by_admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rt_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `fk_rt_requested_by` FOREIGN KEY (`requested_by_admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per refund request; ON DELETE RESTRICT protects refunded orders from deletion';
/*!40101 SET character_set_client = @saved_cs_client */;

